import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookie = response
    .headersArray()
    .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "logout sets a session cookie header").toBeDefined();
  // The value may be serialized as `session=;` or `session="";`; compare the unquoted value.
  const cookieValue = (cookie?.value ?? "").split(";")[0].slice("session=".length).replace(/^"|"$/g, "");
  expect(cookieValue, "session cookie value is emptied").toBe("");
  expect(cookie?.value.toLowerCase(), "session cookie is expired").toMatch(
    /max-age=0|expires=thu, 01 jan 1970/,
  );
});
